-- HAND-EDITED (1): btree_gist extension required for GiST exclusion constraints.
CREATE EXTENSION IF NOT EXISTS btree_gist;--> statement-breakpoint

-- HAND-EDITED (2): UUIDv7 generator function.
-- Encodes the current millisecond unix timestamp into bits 0-47 of the UUID,
-- sets the version nibble to 7 (bits 76-79) and the variant bits (bits 64-65),
-- and fills the remaining bits with cryptographic randomness.
-- This produces time-ordered, globally unique identifiers suitable for B-tree
-- index locality during bulk ingest.
CREATE OR REPLACE FUNCTION uuid_generate_v7()
RETURNS uuid
LANGUAGE plpgsql
AS $$
DECLARE
  unix_ms bigint;
  hex     text;
BEGIN
  -- Current time in milliseconds since Unix epoch (48 bits).
  unix_ms := (extract(epoch FROM clock_timestamp()) * 1000)::bigint;
  -- Encode: 12 hex digits of timestamp + version nibble '7' + 3 hex random
  --         + variant nibble (8|9|a|b) + 12 hex random.
  -- Layout: tttttttttttt-7xxx-Vxxxxxxxxxxx  (where V is the variant nibble)
  hex :=
    lpad(to_hex(unix_ms), 12, '0') ||             -- 48-bit timestamp (12 hex)
    '7' || lpad(to_hex((random() * 4095)::int), 3, '0') ||  -- version 7 + 12 random bits
    to_hex(8 + (random() * 3)::int) ||            -- variant: 1000|1001|1010|1011 (hex 8-b)
    lpad(to_hex((random() * 1099511627775)::bigint), 11, '0') || -- 44 random bits
    lpad(to_hex((random() * 281474976710655)::bigint), 12, '0'); -- 48 random bits
  RETURN (
    substr(hex, 1, 8)  || '-' ||
    substr(hex, 9, 4)  || '-' ||
    substr(hex, 13, 4) || '-' ||
    substr(hex, 17, 4) || '-' ||
    substr(hex, 21, 12)
  )::uuid;
END;
$$;--> statement-breakpoint

